import {Engine,CLASSES,ABILITIES,outcomeSummary} from './engine.js';
import {upgradeInfo,buildSummary,skillName} from './build-info.js';
import {Renderer} from './renderer.js';
import {readSave,exportSave,importSave,SAVE_KEY} from './save.js';
import {forgeCost} from './progression.js';
import {transactSave} from './save-transactions.js';
import {JoystickState,acceptsGameplayKey} from './input.js';
import {executeCommand} from './console.js';
const $=id=>document.getElementById(id);
let {save,storageOK,recovered,writeBlocked,reason:recoveryReason,protectedRaw}=readSave();
let memoryOnly=!storageOK&&!writeBlocked,settlementResult=null,panelEpoch=0,modalSaving=false;
const slotNames={weapon:'武器',armor:'鎧甲',boots:'戰靴'},icons={knight:'⚔',elf:'➶',mage:'✧'};let tutorialSeen=save.best>0;let selected='knight',game=null,lastStatus='',lastLevel=0,claimed=false,audioOn=false,audioCtx;
const renderer=new Renderer($('world')),keys=new Set(),stick=new JoystickState();
async function applyProgress(operation){const result=await transactSave(operation,save,{memoryOnly});if(result.ok)save=result.save;storageOK=result.storageOK;writeBlocked=!!result.writeBlocked;memoryOnly=!!result.memoryOnly;protectedRaw=result.protectedRaw||readSave().protectedRaw;campInfo();return result;}
function campInfo(){$('equipment').textContent=Object.entries(save.equipment).map(([k,v])=>`${slotNames[k]} ${v?'＋'+v:'—'}`).join('　');$('save-note').textContent=storageOK?`本機傳承 · 最長 ${format(save.best)} · 勝利 ${save.wins} 次 · ${save.gold} 金幣`:writeBlocked?'偵測到較新版存檔：此版停止寫入，請先備份':'本頁進度尚未儲存；關閉前請匯出備份';}
function classes(){$('classes').replaceChildren(...Object.entries(CLASSES).map(([id,c])=>{const b=document.createElement('button');b.className='class-card'+(id===selected?' selected':'');b.setAttribute('aria-pressed',String(id===selected));b.innerHTML=`<span class="icon">${icons[id]}</span><b>${c.name}</b><small>${c.weapon}<br>${id==='knight'?'近戰・厚甲生存':id==='elf'?'遠程・迅捷貫穿':'法術・範圍爆破'}</small>`;b.onclick=()=>{selected=id;classes();};return b;}));$('profession-note').textContent=`${ABILITIES[selected].name} · ${ABILITIES[selected].description}（空白鍵 / 職業技按鈕）`;}
function toast(text){$('toast').textContent=text;$('toast').style.opacity=1;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.opacity=0,2800);}
function sound(freq=440){if(!audioOn)return;try{audioCtx??=new AudioContext();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,audioCtx.currentTime);g.gain.setValueAtTime(.025,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.15);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.15);}catch{}}
function start(){game=new Engine(selected,save.equipment,Date.now());claimed=false;settlementResult=null;lastStatus='';lastLevel=1;keys.clear();resetStick();$('camp').hidden=true;$('footer').hidden=true;$('hud').hidden=false;closeModal();document.body.classList.add('playing');$('class-name').textContent=CLASSES[selected].name+' · '+CLASSES[selected].weapon;toast('自動攻擊已啟動。移動收集翠綠靈魂，留意橘紅敵彈。');sound(220);}
function returnCamp(){game=null;keys.clear();resetStick();$('camp').hidden=false;$('hud').hidden=true;closeModal();$('footer').hidden=false;document.body.classList.remove('playing');campInfo();}
function format(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
function action(label,fn,primary=false){const b=document.createElement('button');b.textContent=label;b.className=primary?'primary':'';b.onclick=fn;return b;}
function closeModal(){if(modalSaving)return;panelEpoch++;$('modal').hidden=true;$('camp').inert=false;$('hud').inert=false;document.querySelector('header').inert=false;}
function setModal(kicker,title,description){panelEpoch++;$('camp').inert=true;$('hud').inert=true;document.querySelector('header').inert=true;$('modal').hidden=false;$('modal-kicker').textContent=kicker;$('modal-title').textContent=title;$('modal-description').textContent=description;$('modal-content').replaceChildren();$('modal-actions').replaceChildren();keys.clear();resetStick();}
function syncStatus(){if(!game||game.status===lastStatus&&game.level===lastLevel)return;lastStatus=game.status;lastLevel=game.level;if(game.status==='playing'){closeModal();return;}if(game.status==='upgrade'){setModal('SOUL AWAKENING · LV '+game.level,'靈魂覺醒','時間已停止。選擇一項祝福，改變這場遠征。');const div=document.createElement('div');div.className='upgrade-options';game.choices.forEach(c=>{const info=upgradeInfo(game.classId,c.id,game.upgrades[c.id]);const b=document.createElement('button'),title=document.createElement('strong'),tier=document.createElement('small'),description=document.createElement('small');title.textContent=info.name;tier.textContent=`第 ${info.nextLevel} 階${info.evolves?' · 進化':''}`;description.textContent=info.description;title.append(tier);b.append(title,description);if(info.evolves)b.classList.add('evolution-choice');b.onclick=()=>{if(game.chooseUpgrade(c.id)){sound(620);lastStatus='';syncStatus();}};div.append(b);});$('modal-content').append(div);sound(550);}
 else if(game.status==='paused'){setModal('A MOMENT OF SILENCE','暫歇，為了走得更遠','WASD / 方向鍵移動，空白鍵職業技，Q 治療，Esc 繼續。返回營地將放棄本次未結算戰利品。');$('modal-actions').append(action('繼續遠征',()=>{game.togglePause();syncStatus();},true),action('返回營地',returnCamp));addBuildSummary();addBattleGuide();addDiagnostics();}
 else if(['dead','victory','retreat'].includes(game.status)){
  if(!claimed){claimed=true;setModal('SETTLING','正在結算戰利品','正在安全合併本局成果與最新傳承，請稍候。');const run=game;applyProgress({type:'settle',rewards:run.rewards,time:run.time,won:run.status==='victory'}).then(result=>{if(game!==run)return;settlementResult=result;lastStatus='';syncStatus();});return;}
  if(!settlementResult)return;
  const won=game.status==='victory',summary=outcomeSummary(game);
  setModal(won?'DAWN HAS COME':game.status==='retreat'?'RETURN AT DAWN':'THE FOREST REMEMBERS',summary.title,summary.reason);
  $('modal-content').innerHTML=`<div class="stats"><span><b>${format(game.time)}</b>生存時間</span><span><b>${game.kills}</b>擊倒魔物</span><span><b>${game.rewards.gold}</b>本局金幣</span></div><p>${summary.advice}</p><p>${game.rewards.drop?`取得 ${slotNames[game.rewards.drop.slot]} ＋${game.rewards.drop.tier}`:'本局未取得裝備'}</p><div class="damage-row"><span>傷害來源</span><span>有效傷害</span></div>`;
  if(!settlementResult.storageOK){const notice=document.createElement('p');notice.className='save-warning';notice.textContent=settlementResult.message;$('modal-content').prepend(notice);}
  for(const [k,v]of Object.entries(game.damage)){const r=document.createElement('div');r.className='damage-row';r.innerHTML=`<span>${k==='ability'?ABILITIES[selected].name:skillName(game.classId,k,game.upgrades[k])}</span><span>${Math.round(v).toLocaleString()}</span>`;$('modal-content').append(r);}
  if(settlementResult.ok)$('modal-actions').append(action('再次遠征',start,true),action('返回營地',returnCamp));
  else $('modal-actions').append(action('重新嘗試結算',()=>{claimed=false;lastStatus='';syncStatus();},true));
  sound(won?660:140);
 }
 const focus=$('modal-actions').querySelector('button')||modalFocusables()[0];focus?.focus({preventScroll:true});}
function hud(){if(!game)return;const p=game.player;$('ability-name').textContent=ABILITIES[selected].name;$('ability-cooldown').textContent=game.abilityCooldown>0?Math.ceil(game.abilityCooldown)+'s':'就緒';$('ability').disabled=game.status!=='playing'||game.abilityCooldown>0;$('health').textContent=`${Math.ceil(p.hp)} / ${p.maxHp}`;$('hp-fill').style.width=`${p.hp/p.maxHp*100}%`;$('xp-fill').style.width=`${game.xp/game.xpNext*100}%`;$('timer').textContent=format(game.time);$('level').textContent=`等級 ${game.level}`;$('kills').textContent=`擊倒 ${game.kills}`;$('wave').textContent=game.bossDefeated?'君王已倒下':game.time>=420?'君王降臨 · 黎明前擊倒':`魔潮 ${Math.floor(game.time/60)+1}`;$('potions').textContent=game.potions;$('heal').disabled=game.status!=='playing'||game.potions===0||p.hp>=p.maxHp;const boss=game.enemies.find(e=>e.type==='boss');$('boss').hidden=!boss;if(boss)$('boss-fill').style.width=`${Math.max(0,boss.hp/boss.maxHp)*100}%`;$('skills').innerHTML=['weapon','orb','lightning'].filter(k=>k==='weapon'||game.upgrades[k]).map(k=>`<span>${skillName(game.classId,k,game.upgrades[k])} ${game.upgrades[k]>=5?'✦':`＋${game.upgrades[k]}`}</span>`).join('');}
$('start').onclick=()=>{if(tutorialSeen)start();else showGuide(true);};$('guide').onclick=()=>showGuide(false);$('forge').onclick=showForge;$('backup').onclick=showBackup;$('ability').onclick=useAbility;$('touch').onclick=()=>{const enabled=document.body.classList.toggle('touch-controls');$('touch').textContent=enabled?'觸控：開':'觸控：自動';$('touch').setAttribute('aria-pressed',String(enabled));};$('pause').onclick=()=>{game?.togglePause();syncStatus();};$('heal').onclick=()=>{if(game?.heal())sound(700);};$('sound').onclick=()=>{audioOn=!audioOn;$('sound').textContent='音效：'+(audioOn?'開':'關');sound();};
function modalFocusables(){return [...$('modal').querySelectorAll('button:not([disabled]),input,textarea,select,summary')].filter(el=>el.getClientRects().length>0);}
window.addEventListener('keydown',e=>{
 const k=e.key.toLowerCase();
 if(k==='tab'&&!$('modal').hidden){const targets=modalFocusables(),first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}return;}
 if(k==='escape'){if(e.repeat||modalSaving)return;e.preventDefault();if(game){game.togglePause();syncStatus();}else closeModal();return;}
 if(!acceptsGameplayKey({status:game?.status,modalOpen:!$('modal').hidden,targetTag:e.target.tagName,key:k}))return;
 if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)&&game)e.preventDefault();
 if(e.repeat)return;if(k==='q'&&game?.heal())sound(700);if(k===' ')useAbility();keys.add(k);
});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function autoPause(){keys.clear();resetStick();if(game?.status==='playing'){game.togglePause();syncStatus();}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{if(document.hidden)autoPause();});
const joystick=$('joystick');
function renderStick(){joystick.firstElementChild.style.transform=`translate(${stick.dx}px,${stick.dy}px)`;}
function resetStick(){const id=stick.pointerId;stick.reset();renderStick();if(id!==null&&joystick.hasPointerCapture(id))joystick.releasePointerCapture(id);}
function moveStick(e){if(stick.move(e.pointerId,e.clientX,e.clientY,joystick.getBoundingClientRect(),joystick.firstElementChild.getBoundingClientRect().width))renderStick();}
joystick.onpointerdown=e=>{if(game?.status!=='playing')return;if(stick.begin(e.pointerId,e.clientX,e.clientY,joystick.getBoundingClientRect(),joystick.firstElementChild.getBoundingClientRect().width)){try{joystick.setPointerCapture(e.pointerId);renderStick();}catch{resetStick();}}};
joystick.onpointermove=moveStick;
function endStick(e){if(stick.end(e.pointerId))renderStick();}
joystick.onpointerup=endStick;joystick.onpointercancel=endStick;joystick.onlostpointercapture=endStick;
let last=performance.now(),ui=0;function frame(now){let dt=Math.min(.05,(now-last)/1000);last=now;if(game){game.update(dt,inputVector());syncStatus();ui+=dt;if(ui>.1){hud();ui=0;}}renderer.render(game,game?.time??now/1000);requestAnimationFrame(frame);}classes();campInfo();if(recovered)toast(recoveryReason==='backup'?'已從備份復原傳承。建議匯出一份安全備份。':'存檔無法讀取且沒有有效備份；已開啟新傳承。');requestAnimationFrame(frame);
function inputVector(){return {x:stick.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y:stick.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)};}
function useAbility(){if(game?.useAbility(inputVector())){sound(360);toast(ABILITIES[selected].name);}}
function showForge(){setModal('LEGACY FORGE','把戰利品，鍛成下一次勝算。',`持有 ${save.gold} 金幣。每次提升一階，最高 ＋5；掉落不會降低已鍛造裝備。`);const grid=document.createElement('div');grid.className='forge-grid';for(const slot of ['weapon','armor','boots']){const tier=save.equipment[slot],cost=forgeCost(save,slot);const card=document.createElement('section');card.innerHTML=`<h3>${slotNames[slot]} ＋${tier}</h3><p>${slot==='weapon'?'每階傷害 ＋8%':slot==='armor'?'每階生命 ＋10、減傷 ＋1':'每階移速 ＋5'}</p>`;const b=action(tier>=5?'已達最高階':`鍛造 ＋${tier+1} · ${cost} 金`,async()=>{b.disabled=true;const epoch=panelEpoch;const result=await applyProgress({type:'forge',slot});if(epoch!==panelEpoch){toast(result.message);return;}showForge();const notice=document.createElement('p');notice.className=result.storageOK?'':'save-warning';notice.textContent=result.message;$('modal-content').append(notice);toast(result.message);});b.disabled=tier>=5||save.gold<cost||writeBlocked;card.append(b);grid.append(card);}$('modal-content').append(grid);$('modal-actions').append(action('返回營地',()=>{closeModal();$('forge').focus();}));$('modal-actions').querySelector('button').focus();}
function showBackup(){
 setModal('KEEP YOUR LEGACY','傳承備份',protectedRaw?'偵測到不相容版本。下方保留原始存檔，只能複製，不能在此版覆寫。':'複製備份碼保存在安全位置；匯入會取代目前傳承。只處理本機資料，不會上傳。');
 const label=document.createElement('label');label.textContent=protectedRaw?'受保護的原始存檔':'傳承備份碼';label.htmlFor='save-code';const area=document.createElement('textarea');area.id='save-code';area.rows=7;area.spellcheck=false;area.value=protectedRaw||exportSave(save);area.readOnly=!!protectedRaw;const status=document.createElement('p');status.setAttribute('role','status');$('modal-content').append(label,area,status);
 $('modal-actions').append(action('選取備份碼',()=>{area.focus();area.select();}));
 if(protectedRaw&&memoryOnly){const ownLabel=document.createElement('label');ownLabel.textContent='本頁暫存進度（不是上方原始存檔）';ownLabel.htmlFor='memory-code';const ownArea=document.createElement('textarea');ownArea.id='memory-code';ownArea.rows=5;ownArea.readOnly=true;ownArea.value=exportSave(save);$('modal-content').append(ownLabel,ownArea);$('modal-actions').append(action('選取本頁進度',()=>{ownArea.focus();ownArea.select();}));}
 if(!protectedRaw)$('modal-actions').append(action('檢查匯入',()=>{const result=importSave(area.value);if(!result.ok){status.textContent=result.message;return;}setModal('CONFIRM IMPORT','取代本機傳承？',`即將匯入 ${result.save.gold} 金幣、最高 ${format(result.save.best)}。儲存成功才會取代；備援仍受瀏覽器空間限制，建議先自行複製目前資料。`);$('modal-actions').append(action('確認取代',async()=>{const confirm=$('modal-actions').firstElementChild;modalSaving=true;for(const button of $('modal-actions').querySelectorAll('button'))button.disabled=true;const saved=await applyProgress({type:'import',save:result.save});modalSaving=false;for(const button of $('modal-actions').querySelectorAll('button'))button.disabled=false;if(saved.ok){closeModal();toast(saved.message);}else{const notice=document.createElement('p');notice.className='save-warning';notice.textContent=saved.message;$('modal-content').replaceChildren(notice);confirm.disabled=false;}},true),action('取消',showBackup));$('modal-actions').lastElementChild.focus();}));
 $('modal-actions').append(action('關閉',()=>closeModal()));area.focus();
}
window.addEventListener('storage',event=>{if(event.key!==SAVE_KEY&&event.key!==null)return;if(memoryOnly){toast('另一分頁更新了傳承；本頁尚有未儲存進度，請先匯出備份。');return;}const latest=readSave();save=latest.save;storageOK=latest.storageOK;writeBlocked=!!latest.writeBlocked;protectedRaw=latest.protectedRaw;campInfo();if(game?.status==='playing')autoPause();if(!$('modal').hidden&&$('modal-kicker').textContent==='LEGACY FORGE')showForge();toast('已讀取另一分頁的新傳承；本局角色能力不變，結算時會合併最新成果。');});
function addDiagnostics(){const details=document.createElement('details');details.className='diagnostics';const summary=document.createElement('summary');summary.textContent='遠征情報 · 唯讀指令';const form=document.createElement('form');const input=document.createElement('input');input.placeholder='help / status / player / skills';input.setAttribute('aria-label','遠征情報指令');input.maxLength=80;const output=document.createElement('output');output.setAttribute('aria-live','polite');const button=document.createElement('button');button.type='submit';button.textContent='查詢';form.append(input,button);form.onsubmit=e=>{e.preventDefault();output.textContent=executeCommand(input.value,game).message;};details.append(summary,form,output);$('modal-content').append(details);}

function guideContents(){const guide=document.createElement('div');guide.className='field-guide';guide.innerHTML=`<div><b>① 移動，就是生存</b><p>WASD／方向鍵，或開啟觸控搖桿。攻擊會自動瞄準，不必停下來。</p></div><div><b>② 翠綠靈魂 → 升級</b><p>靠近翠綠結晶收集經驗。升級三選一時時間停止；武器／聖焰／雷霆第五階進化。</p></div><div><b>③ 橘色虛線 → 即將開火</b><p>法師與君王會先瞄準約 0.6 秒，再沿警示方向射擊。側移離開射線，別硬吃橘紅彈幕。</p></div><div><b>④ 職業技與治療</b><p>空白鍵／右側職業技按鈕：${ABILITIES[selected].name}。Q／治療按鈕每局三瓶；滿血不浪費藥水。</p></div><div><b>⑤ 擊倒君王，迎接黎明</b><p>第 7 分鐘君王降臨。擊倒君王且活到 8 分鐘才算勝利；8 分鐘仍未擊倒則撤離結算，不會無限延長。裝備和金幣帶回營地，鍛造下一次勝算。</p></div>`;return guide;}
function showGuide(firstRun=false){setModal('FIELD GUIDE',firstRun?'第一次遠征，先記住這五件事。':'暮林生存指南','這裡沒有倒數壓力。準備好再出發。');$('modal-content').append(guideContents());$('modal-actions').append(action(firstRun?'我準備好了，出發':'返回營地',()=>{if(firstRun){tutorialSeen=true;start();}else closeModal();},true));if(firstRun)$('modal-actions').append(action('暫不出發',()=>closeModal()));$('modal-actions').firstElementChild.focus();}
function addBattleGuide(){const details=document.createElement('details');details.className='diagnostics';const summary=document.createElement('summary');summary.textContent='戰場指南 · 操作與危險提示';details.append(summary,guideContents());$('modal-content').append(details);}

function addBuildSummary(){const details=document.createElement('details');details.className='diagnostics build-summary';const summary=document.createElement('summary');summary.textContent='本局流派 · 技能與裝備效果';const list=document.createElement('dl');for(const item of buildSummary(game).filter(item=>item.active!==false)){const name=document.createElement('dt'),description=document.createElement('dd');name.textContent=item.name+(Number.isInteger(item.level)?` ＋${item.level}`:'');description.textContent=item.description;list.append(name,description);}details.append(summary,list);$('modal-content').append(details);}
